css:
@keyframes gemini-neon-hum {
  0%, 100% { opacity: 0.45; }
  45% { opacity: 0.95; }
  50% { opacity: 0.82; }
  53% { opacity: 1; }
  78% { opacity: 0.62; }
  80% { opacity: 0.48; }
  82% { opacity: 0.72; }
}

.dark [data-workspace-area="conversation"] {
  background:
    radial-gradient(ellipse 68% 42% at 50% 0%, rgba(255, 100, 24, 0.11), transparent 72%),
    radial-gradient(ellipse 48% 34% at 88% 100%, rgba(196, 52, 10, 0.08), transparent 70%),
    #0b0705 !important;
}

/* Steady resting neon-tube glow on the composer card (when no shoulder tab/banner is attached) */
.dark [data-slot="composer-host"]:not(:has([data-composer-banner-surface="attached"])) {
  position: relative !important;
  border: 1.5px solid #ffd29d !important;
  box-shadow:
    inset 0 0 8px rgba(255, 132, 46, 0.45),
    0 0 4px rgba(255, 224, 178, 0.72),
    0 0 12px rgba(255, 108, 28, 0.68),
    0 0 26px rgba(255, 86, 16, 0.42),
    0 0 48px rgba(214, 54, 8, 0.26) !important;
  transition: border-color 140ms ease !important;
}

/* When Stash / attached banner is present, wrap the neon frame around the rounded main composer card */
.dark [data-slot="composer-host"]:has([data-composer-banner-surface="attached"]) [data-chat-composer-main-surface="true"] {
  position: relative !important;
  border: 1.5px solid #ffd29d !important;
  box-shadow:
    inset 0 0 8px rgba(255, 132, 46, 0.45),
    0 0 4px rgba(255, 224, 178, 0.72),
    0 0 12px rgba(255, 108, 28, 0.68),
    0 0 26px rgba(255, 86, 16, 0.42),
    0 0 48px rgba(214, 54, 8, 0.26) !important;
  transition: border-color 140ms ease !important;
}

/* GPU-composited opacity-only overlay for the focused neon hum/pulse */
.dark [data-slot="composer-host"]:not(:has([data-composer-banner-surface="attached"]))::after,
.dark [data-slot="composer-host"]:has([data-composer-banner-surface="attached"]) [data-chat-composer-main-surface="true"]::after {
  content: "" !important;
  position: absolute !important;
  inset: -1.5px !important;
  border-radius: inherit !important;
  pointer-events: none !important;
  border: 1.5px solid #fff2dc !important;
  box-shadow:
    inset 0 0 12px rgba(255, 152, 66, 0.65),
    0 0 7px rgba(255, 238, 208, 0.95),
    0 0 18px rgba(255, 114, 32, 0.9),
    0 0 38px rgba(255, 86, 16, 0.62),
    0 0 66px rgba(214, 54, 8, 0.38) !important;
  opacity: 0 !important;
  transition: opacity 180ms ease !important;
  will-change: opacity !important;
}

/* Stash shoulder tab: continues the neon contour around the top-right shoulder tab without crossing the seam */
.dark [data-composer-shoulder-tab] {
  position: relative !important;
  z-index: 25 !important;
  pointer-events: none !important;
  padding-bottom: calc(var(--composer-banner-padding-block, 0.3125rem) + 1rem + 1px) !important;
  clip-path: inset(-80px -80px calc(1rem - 0.5px) -80px) !important;
}

.dark [data-composer-shoulder-tab] [data-prompt-stash-badge] {
  pointer-events: auto !important;
}

.dark [data-composer-shoulder-tab]::before {
  content: "" !important;
  position: absolute !important;
  inset: 0 !important;
  z-index: -1 !important;
  pointer-events: none !important;
  border-top-left-radius: calc(var(--radius) + 8px) !important;
  border-top-right-radius: calc(var(--radius) + 8px) !important;
  border: 1.5px solid #ffd29d !important;
  border-bottom: 0 !important;
  background: color-mix(in srgb, var(--app-theme-surface-raised, #1d110b) 84%, var(--app-theme-canvas, #0b0705)) !important;
  -webkit-mask-image: none !important;
  mask-image: none !important;
  box-shadow:
    inset 0 0 8px rgba(255, 132, 46, 0.45),
    0 0 4px rgba(255, 224, 178, 0.72),
    0 0 12px rgba(255, 108, 28, 0.68),
    0 0 26px rgba(255, 86, 16, 0.42),
    0 0 48px rgba(214, 54, 8, 0.26) !important;
  transition: border-color 140ms ease !important;
}

.dark [data-composer-shoulder-tab]::after {
  content: "" !important;
  display: block !important;
  position: absolute !important;
  inset: 0 !important;
  height: auto !important;
  z-index: 1 !important;
  pointer-events: none !important;
  border-top-left-radius: calc(var(--radius) + 8px) !important;
  border-top-right-radius: calc(var(--radius) + 8px) !important;
  border: 1.5px solid #fff2dc !important;
  border-bottom: 0 !important;
  box-shadow:
    inset 0 0 12px rgba(255, 152, 66, 0.65),
    0 0 7px rgba(255, 238, 208, 0.95),
    0 0 18px rgba(255, 114, 32, 0.9),
    0 0 38px rgba(255, 86, 16, 0.62),
    0 0 66px rgba(214, 54, 8, 0.38) !important;
  opacity: 0 !important;
  transition: opacity 180ms ease !important;
  will-change: opacity !important;
}

.dark [data-slot="composer-host"]:not(:has([data-composer-banner-surface="attached"])):focus-within::after,
.dark [data-slot="composer-host"]:has([data-composer-banner-surface="attached"]):focus-within [data-chat-composer-main-surface="true"]::after,
.dark [data-slot="composer-host"]:has([data-composer-banner-surface="attached"]):focus-within [data-composer-shoulder-tab]::after {
  opacity: 0.85 !important;
  animation: gemini-neon-hum 3.4s ease-in-out infinite !important;
}

@media (prefers-reduced-motion: reduce) {
  .dark [data-slot="composer-host"]:not(:has([data-composer-banner-surface="attached"])):focus-within::after,
  .dark [data-slot="composer-host"]:has([data-composer-banner-surface="attached"]):focus-within [data-chat-composer-main-surface="true"]::after,
  .dark [data-slot="composer-host"]:has([data-composer-banner-surface="attached"]):focus-within [data-composer-shoulder-tab]::after {
    animation: none !important;
    opacity: 0.85 !important;
  }
}

.dark [data-user-message-bubble] {
  border: 1px solid rgba(255, 122, 41, 0.28) !important;
  background: linear-gradient(135deg, #27150c, #1d100a) !important;
}

.dark .chat-markdown-codeblock {
  border-left: 2px solid #ff6a1a !important;
}

.dark [data-thread-item][data-active="true"],
.dark [data-thread-item][aria-current="page"] {
  box-shadow: inset 2px 0 0 #ff7a29, inset 8px 0 14px -8px rgba(255, 115, 36, 0.55) !important;
}
